export function buildReadModel(records=[],{key='id',version='v1'}={}){const map=new Map();for(const r of records){const id=r?.[key];if(id===undefined||id===null)continue;const old=map.get(id);const nt=Number(new Date(r.updatedAt??r.observedAt??0)),ot=Number(new Date(old?.updatedAt??old?.observedAt??0));if(!old||nt>=ot)map.set(id,r)}return {version,rows:[...map.values()],count:map.size,builtAt:new Date().toISOString()}}
